import paper from '@turbowarp/paper';
import Modes from '../../lib/modes';
import { styleShape } from '../style-path';
import { clearSelection } from '../selection';
import { getSquareDimensions } from '../math';
import BoundingBoxTool from '../selection-tools/bounding-box-tool';
import NudgeTool from '../selection-tools/nudge-tool';

/**
 * Tool for drawing hearts.
 */
class HeartTool extends paper.Tool {
  static get TOLERANCE() {
    return 2;
  }
  /**
   * Outline of a heart normalized to the unit square, y pointing down, listed clockwise
   * starting at the top notch. Sampled from the classic parametric heart curve
   * x = 16sin³t, y = 13cos t - 5cos 2t - 2cos 3t - cos 4t, with the handles set from the
   * curve's own tangents so each pair of nodes reproduces its arc to within 0.7% of the
   * shape's size. Nodes are placed on the notch, both lobe apexes, both widest points and
   * the tip, so the outline touches every edge of the box the user drags. The notch keeps
   * a small handle instead of the curve's true cusp, which would render as a hairline
   * crack at small sizes.
   */
  static get UNIT_SEGMENTS() {
    return [{
      point: [0.5, 0.2394],
      handleIn: [-0.02, 0],
      handleOut: [0.02, 0]
    }, {
      point: [0.5422, 0.1206],
      handleIn: [-0.0392, 0.0624],
      handleOut: [0.0392, -0.0624]
    }, {
      point: [0.7449, 0],
      handleIn: [-0.0868, 0],
      handleOut: [0.0633, 0]
    }, {
      point: [0.9228, 0.0802],
      handleIn: [-0.0482, -0.0508],
      handleOut: [0.0482, 0.0508]
    }, {
      point: [1, 0.2739],
      handleIn: [0, -0.0726],
      handleOut: [0, 0.172]
    }, {
      point: [0.6768, 0.7444],
      handleIn: [0.1388, -0.1353],
      handleOut: [-0.1388, 0.1353]
    }, {
      point: [0.5, 1],
      handleIn: [0, 0],
      handleOut: [0, 0]
    }, {
      point: [0.3232, 0.7444],
      handleIn: [0.1388, 0.1353],
      handleOut: [-0.1388, -0.1353]
    }, {
      point: [0, 0.2739],
      handleIn: [0, 0.172],
      handleOut: [0, -0.0726]
    }, {
      point: [0.0772, 0.0802],
      handleIn: [-0.0482, 0.0508],
      handleOut: [0.0482, -0.0508]
    }, {
      point: [0.2551, 0],
      handleIn: [-0.0633, 0],
      handleOut: [0.0868, 0]
    }, {
      point: [0.4578, 0.1206],
      handleIn: [-0.0392, -0.0624],
      handleOut: [0.0392, 0.0624]
    }];
  }
  /**
   * @param {paper.Rectangle} rect Bounding box to fit the heart into
   * @return {paper.Path} A closed heart shaped path
   */
  static createHeartPath(rect) {
    const w = rect.width;
    const h = rect.height;
    const path = new paper.Path();
    for (const segment of HeartTool.UNIT_SEGMENTS) {
      path.add(new paper.Segment(new paper.Point(rect.left + segment.point[0] * w, rect.top + segment.point[1] * h), new paper.Point(segment.handleIn[0] * w, segment.handleIn[1] * h), new paper.Point(segment.handleOut[0] * w, segment.handleOut[1] * h)));
    }
    path.closed = true;
    return path;
  }
  constructor(setSelectedItems, clearSelectedItems, setCursor, onUpdateImage) {
    super();
    this.setSelectedItems = setSelectedItems;
    this.clearSelectedItems = clearSelectedItems;
    this.onUpdateImage = onUpdateImage;
    this.boundingBoxTool = new BoundingBoxTool(Modes.HEART, setSelectedItems, clearSelectedItems, setCursor, onUpdateImage);
    const nudgeTool = new NudgeTool(Modes.HEART, this.boundingBoxTool, onUpdateImage);
    this.onMouseDown = this.handleMouseDown;
    this.onMouseMove = this.handleMouseMove;
    this.onMouseDrag = this.handleMouseDrag;
    this.onMouseUp = this.handleMouseUp;
    this.onKeyUp = nudgeTool.onKeyUp;
    this.onKeyDown = nudgeTool.onKeyDown;
    this.heart = null;
    this.colorState = null;
    this.isBoundingBoxMode = null;
    this.active = false;
  }
  getHitOptions() {
    return {
      segments: true,
      stroke: true,
      curves: true,
      fill: true,
      guide: false,
      match: hitResult => hitResult.item.data && (hitResult.item.data.isScaleHandle || hitResult.item.data.isRotHandle) || hitResult.item.selected,
      tolerance: HeartTool.TOLERANCE / paper.view.zoom
    };
  }
  onSelectionChanged(selectedItems) {
    this.boundingBoxTool.onSelectionChanged(selectedItems);
  }
  setColorState(colorState) {
    this.colorState = colorState;
  }
  handleMouseDown(event) {
    if (event.event.button > 0) return;
    this.active = true;
    if (this.boundingBoxTool.onMouseDown(event, false, false, false, this.getHitOptions())) {
      this.isBoundingBoxMode = true;
    } else {
      this.isBoundingBoxMode = false;
      clearSelection(this.clearSelectedItems);
    }
  }
  handleMouseDrag(event) {
    if (event.event.button > 0 || !this.active) return;
    if (this.isBoundingBoxMode) {
      this.boundingBoxTool.onMouseDrag(event);
      return;
    }
    if (this.heart) {
      this.heart.remove();
    }
    const rect = new paper.Rectangle(event.downPoint, event.point);
    const squareDimensions = getSquareDimensions(event.downPoint, event.point);
    if (event.modifiers.shift) {
      rect.size = squareDimensions.size.abs();
    }
    this.heart = HeartTool.createHeartPath(rect);
    if (event.modifiers.alt) {
      this.heart.position = event.downPoint;
    } else if (event.modifiers.shift) {
      this.heart.position = squareDimensions.position;
    } else {
      const dimensions = event.point.subtract(event.downPoint);
      this.heart.position = event.downPoint.add(dimensions.multiply(0.5));
    }
    styleShape(this.heart, this.colorState);
  }
  handleMouseUp(event) {
    if (event.event.button > 0 || !this.active) return;
    if (this.isBoundingBoxMode) {
      this.boundingBoxTool.onMouseUp(event);
      this.isBoundingBoxMode = null;
      return;
    }
    if (this.heart) {
      if (Math.abs(this.heart.area) < HeartTool.TOLERANCE / paper.view.zoom) {
        this.heart.remove();
        this.heart = null;
      } else {
        this.heart.selected = true;
        this.setSelectedItems();
        this.onUpdateImage();
        this.heart = null;
      }
    }
    this.active = false;
  }
  handleMouseMove(event) {
    this.boundingBoxTool.onMouseMove(event, this.getHitOptions());
  }
  deactivateTool() {
    this.boundingBoxTool.deactivateTool();
  }
}
export default HeartTool;