import paper from '@turbowarp/paper';
import { getGuideLayer } from '../layer';

/**
 * Tool to handle rotation when dragging the rotation handle in the bounding box tool.
 */
class RotateTool {
  /**
   * @param {!function} onUpdateImage A callback to call when the image visibly changes
   */
  constructor(onUpdateImage) {
    this.rotItems = [];
    this.rotGroupPivot = null;
    this.prevRot = 90;
    this.onUpdateImage = onUpdateImage;
    this.angleTooltip = null;
  }
  _removeAngleTooltip() {
    if (this.angleTooltip) {
      this.angleTooltip.remove();
      this.angleTooltip = null;
    }
  }
  _updateAngleTooltip(event, angle) {
    const zoom = paper.view.zoom;
    const fontSize = 11 / zoom;
    const padding = 4 / zoom;
    const offsetX = 16 / zoom;
    const offsetY = -16 / zoom;
    const displayAngle = Math.round(angle);
    const text = "".concat(displayAngle, "\xB0");
    if (!this.angleTooltip) {
      const guideLayer = getGuideLayer();
      this.angleTooltip = new paper.Group();
      this.angleTooltip.data.isAngleTooltip = true;
      this.angleTooltip.data.isHelperItem = true;
      this.angleTooltip.guide = true;
      this.angleTooltip.locked = true;
      this.angleTooltip.parent = guideLayer;
    }

    // Remove old children
    this.angleTooltip.removeChildren();
    const pointText = new paper.PointText({
      point: new paper.Point(0, 0),
      content: text,
      fillColor: '#ffffff',
      fontSize: fontSize,
      fontFamily: 'sans-serif',
      justification: 'center'
    });
    pointText.data.isHelperItem = true;
    const textBounds = pointText.bounds;
    const bgRect = new paper.Path.Rectangle({
      point: textBounds.topLeft.subtract(new paper.Point(padding, padding)),
      size: textBounds.size.add(new paper.Point(padding * 2, padding * 2)),
      radius: 3 / zoom,
      fillColor: new paper.Color(0, 0, 0, 0.7)
    });
    bgRect.data.isHelperItem = true;
    this.angleTooltip.addChild(bgRect);
    this.angleTooltip.addChild(pointText);
    this.angleTooltip.position = event.point.add(new paper.Point(offsetX, offsetY));
    this.angleTooltip.bringToFront();
  }

  /**
   * @param {!paper.HitResult} hitResult Data about the location of the mouse click
   * @param {!object} boundsPath Where the boundaries of the hit item are
   * @param {!Array.<paper.Item>} selectedItems Set of selected paper.Items
   */
  onMouseDown(hitResult, boundsPath, selectedItems) {
    this.rotGroupPivot = boundsPath.bounds.center;
    for (const item of selectedItems) {
      // Rotate only root items
      if (item.parent instanceof paper.Layer) {
        this.rotItems.push(item);
      }
    }
    this.prevRot = 90;
  }
  onMouseDrag(event) {
    let rotAngle = event.point.subtract(this.rotGroupPivot).angle;
    if (event.modifiers.shift) {
      rotAngle = Math.round(rotAngle / 45) * 45;
    }
    for (let i = 0; i < this.rotItems.length; i++) {
      const item = this.rotItems[i];
      item.rotate(rotAngle - this.prevRot, this.rotGroupPivot);
    }
    this._updateAngleTooltip(event, rotAngle);
    this.prevRot = rotAngle;
  }
  onMouseUp(event) {
    if (event.event.button > 0) return; // only first mouse button

    this._removeAngleTooltip();
    this.rotItems.length = 0;
    this.rotGroupPivot = null;
    this.prevRot = 90;
    this.onUpdateImage();
  }
}
export default RotateTool;