import paper from '@turbowarp/paper';
import Modes from '../../lib/modes';
import { styleShape } from '../style-path';
import { clearSelection } from '../selection';
import { getSquareDimensions } from '../math';
import BoundingBoxTool from '../selection-tools/bounding-box-tool';
import NudgeTool from '../selection-tools/nudge-tool';

/**
 * Tool for drawing double arrows (bidirectional arrows).
 */
class DoubleArrowTool extends paper.Tool {
  static get TOLERANCE() {
    return 2;
  }
  constructor(setSelectedItems, clearSelectedItems, setCursor, onUpdateImage) {
    super();
    this.setSelectedItems = setSelectedItems;
    this.clearSelectedItems = clearSelectedItems;
    this.onUpdateImage = onUpdateImage;
    this.boundingBoxTool = new BoundingBoxTool(Modes.DOUBLE_ARROW, setSelectedItems, clearSelectedItems, setCursor, onUpdateImage);
    const nudgeTool = new NudgeTool(Modes.DOUBLE_ARROW, this.boundingBoxTool, onUpdateImage);
    this.onMouseDown = this.handleMouseDown;
    this.onMouseMove = this.handleMouseMove;
    this.onMouseDrag = this.handleMouseDrag;
    this.onMouseUp = this.handleMouseUp;
    this.onKeyUp = nudgeTool.onKeyUp;
    this.onKeyDown = nudgeTool.onKeyDown;
    this.arrow = null;
    this.colorState = null;
    this.isBoundingBoxMode = null;
    this.active = false;
  }
  getHitOptions() {
    return {
      segments: true,
      stroke: true,
      curves: true,
      fill: true,
      guide: false,
      match: hitResult => hitResult.item.data && (hitResult.item.data.isScaleHandle || hitResult.item.data.isRotHandle) || hitResult.item.selected,
      tolerance: DoubleArrowTool.TOLERANCE / paper.view.zoom
    };
  }
  onSelectionChanged(selectedItems) {
    this.boundingBoxTool.onSelectionChanged(selectedItems);
  }
  setColorState(colorState) {
    this.colorState = colorState;
  }
  handleMouseDown(event) {
    if (event.event.button > 0) return;
    this.active = true;
    if (this.boundingBoxTool.onMouseDown(event, false, false, false, this.getHitOptions())) {
      this.isBoundingBoxMode = true;
    } else {
      this.isBoundingBoxMode = false;
      clearSelection(this.clearSelectedItems);
    }
  }
  handleMouseDrag(event) {
    if (event.event.button > 0 || !this.active) return;
    if (this.isBoundingBoxMode) {
      this.boundingBoxTool.onMouseDrag(event);
      return;
    }
    if (this.arrow) {
      this.arrow.remove();
    }
    const rect = new paper.Rectangle(event.downPoint, event.point);
    const squareDimensions = getSquareDimensions(event.downPoint, event.point);
    if (event.modifiers.shift) {
      rect.size = squareDimensions.size.abs();
    }
    const x1 = rect.left;
    const x2 = rect.right;
    const y1 = rect.top;
    const y2 = rect.bottom;
    const w = rect.width;
    const h = rect.height;

    // Double arrow: arrowheads on both ends, shaft in the middle
    // Each arrowhead takes 30% of width, shaft height is 40% of total height
    const headW = 0.3 * w;
    const shaftTop = y1 + 0.3 * h;
    const shaftBottom = y1 + 0.7 * h;
    const midY = y1 + 0.5 * h;
    this.arrow = new paper.Path();
    // Left tip
    this.arrow.add(new paper.Point(x1, midY));
    // Left arrowhead top
    this.arrow.add(new paper.Point(x1 + headW, y1));
    // Shaft top-left
    this.arrow.add(new paper.Point(x1 + headW, shaftTop));
    // Shaft top-right
    this.arrow.add(new paper.Point(x2 - headW, shaftTop));
    // Right arrowhead top
    this.arrow.add(new paper.Point(x2 - headW, y1));
    // Right tip
    this.arrow.add(new paper.Point(x2, midY));
    // Right arrowhead bottom
    this.arrow.add(new paper.Point(x2 - headW, y2));
    // Shaft bottom-right
    this.arrow.add(new paper.Point(x2 - headW, shaftBottom));
    // Shaft bottom-left
    this.arrow.add(new paper.Point(x1 + headW, shaftBottom));
    // Left arrowhead bottom
    this.arrow.add(new paper.Point(x1 + headW, y2));
    this.arrow.closed = true;
    if (event.modifiers.alt) {
      this.arrow.position = event.downPoint;
    } else if (event.modifiers.shift) {
      this.arrow.position = squareDimensions.position;
    } else {
      const dimensions = event.point.subtract(event.downPoint);
      this.arrow.position = event.downPoint.add(dimensions.multiply(0.5));
    }
    styleShape(this.arrow, this.colorState);
  }
  handleMouseUp(event) {
    if (event.event.button > 0 || !this.active) return;
    if (this.isBoundingBoxMode) {
      this.boundingBoxTool.onMouseUp(event);
      this.isBoundingBoxMode = null;
      return;
    }
    if (this.arrow) {
      if (Math.abs(this.arrow.area) < DoubleArrowTool.TOLERANCE / paper.view.zoom) {
        this.arrow.remove();
        this.arrow = null;
      } else {
        this.arrow.selected = true;
        this.setSelectedItems();
        this.onUpdateImage();
        this.arrow = null;
      }
    }
    this.active = false;
  }
  handleMouseMove(event) {
    this.boundingBoxTool.onMouseMove(event, this.getHitOptions());
  }
  deactivateTool() {
    this.boundingBoxTool.deactivateTool();
  }
}
export default DoubleArrowTool;